#!/bin/bash
# Kansas City run registry adds, part 4 of 10. Run once from the registry folder after: source ./.env
ADDED=0; REFUSED=0; REFUSED_LIST=""
if python3 registry.py add --slug yayas-alpaca-farm-annual-christmas-garden-city-mo --name 'Yaya'"'"'s Alpaca Farm Annual Christmas' --city 'Garden City' --cc mo --url https://www.visitkc.com/events/yayas-alpaca-farm-annual-christmas/ --date 2026-11-26 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST yayas-alpaca-farm-annual-christmas-garden-city-mo"; fi || true
if python3 registry.py add --slug mayors-holiday-tree-lighting-in-downtown-raytown-mo --name 'Mayor'"'"'s Holiday Tree Lighting in Downtown Raytown' --city Raytown --cc mo --url 'https://www.raytown.mo.us/?event=117' --date 2026-12-05 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST mayors-holiday-tree-lighting-in-downtown-raytown-mo"; fi || true
if python3 registry.py add --slug candlelight-tour-at-fort-osage-national-historic-landmark-sibley-mo --name 'Candlelight Tour at Fort Osage National Historic Landmark' --city Sibley --cc mo --url https://www.jacksongov.org/Home/Tabs/Events/Candlelight-Tour-at-Fort-Osage --date 2026-12-12 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST candlelight-tour-at-fort-osage-national-historic-landmark-sibley-mo"; fi || true
if python3 registry.py add --slug storytime-with-santa-and-mrs-claus-at-withers-library-liberty-mo --name 'Storytime with Santa and Mrs. Claus at Withers Library' --city Liberty --cc mo --url https://www.mymcpl.org/events/122378/storytime-santa-and-mrs-claus --date 2026-12-07 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST storytime-with-santa-and-mrs-claus-at-withers-library-liberty-mo"; fi || true
if python3 registry.py add --slug mayors-christmas-tree-lighting-at-linden-square-gladstone-mo --name 'Mayor'"'"'s Christmas Tree Lighting at Linden Square' --city Gladstone --cc mo --url 'https://www.gladstone.mo.us/calpopup.php?id=3787' --date 2026-12-01 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST mayors-christmas-tree-lighting-at-linden-square-gladstone-mo"; fi || true
if python3 registry.py add --slug photos-and-cookies-with-santa-and-holiday-nights-at-atkins-johnson-gladstone-mo --name 'Photos and Cookies with Santa and Holiday Nights at Atkins-Johnson Farm and Museum' --city Gladstone --cc mo --url https://www.gladstone.mo.us/documents/news/2026/20261119165602.pdf --date 2026-12-05 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST photos-and-cookies-with-santa-and-holiday-nights-at-atkins-johnson-gladstone-mo"; fi || true
if python3 registry.py add --slug mayors-tree-lighting-at-dagg-park-north-kansas-city-mo --name 'Mayor'"'"'s Tree Lighting at Dagg Park' --city 'North Kansas City' --cc mo --url https://www.nkc.org/Home/Components/Calendar/Event/1173/17 --date 2026-12-04 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST mayors-tree-lighting-at-dagg-park-north-kansas-city-mo"; fi || true
if python3 registry.py add --slug kearneys-magical-night-and-lighted-christmas-parade-mo --name 'Kearney'"'"'s Magical Night and Lighted Christmas Parade' --city Kearney --cc mo --url https://www.kearneyenrichmentcouncil.org/kearneys-magical-night --date 2026-12-12 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST kearneys-magical-night-and-lighted-christmas-parade-mo"; fi || true
if python3 registry.py add --slug how-the-grinch-stole-storytime-at-kearney-library-mo --name 'How the Grinch Stole Storytime at Kearney Library' --city Kearney --cc mo --url https://www.mymcpl.org/events/122828/how-grinch-stole-storytime --date 2026-12-01 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST how-the-grinch-stole-storytime-at-kearney-library-mo"; fi || true
if python3 registry.py add --slug candy-cane-quest-at-heritage-park-smithville-mo --name 'Candy Cane Quest at Heritage Park' --city Smithville --cc mo --url https://www.smithvillemo.org/news_detail_T6_R290.php --date 2026-12-04 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST candy-cane-quest-at-heritage-park-smithville-mo"; fi || true
echo "added $ADDED, refused $REFUSED"; [ -n "$REFUSED_LIST" ] && printf "refused slugs:\n%s\n" "$REFUSED_LIST" | tr " " "\n"; true
